import {pdfFonts} from './pdf-fonts.js';
const codes={'€':128,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151};
const bytes=s=>Array.from(String(s??''),c=>codes[c]??(c.charCodeAt(0)<=255?c.charCodeAt(0):63));
const str=s=>'('+bytes(s).map(c=>c<32||c>126?'\\'+c.toString(8).padStart(3,'0'):[40,41,92].includes(c)?'\\'+String.fromCharCode(c):String.fromCharCode(c)).join('')+')';
export function movementPdf(m){
 const out=m.type==='SA',pages=[];let ops=[],y=0;
 const rect=(x,t,w,h,color)=>ops.push(`${color} rg ${x} ${792-t-h} ${w} ${h} re f`);
 const text=(s,x,t,size=10,bold=false,color='0.15 0.22 0.21')=>ops.push(`BT /F${bold?2:1} ${size} Tf ${color} rg 1 0 0 1 ${x} ${792-t-size} Tm ${str(s)} Tj ET`);
 const page=()=>{if(ops.length)pages.push(ops);ops=[];rect(0,0,612,108,'0.12 0.27 0.24');text('EL CLUB DE PON PON',42,22,10,true,'1 1 1');text(out?'Hoja de salida':'Hoja de entrada',42,43,24,true,'1 1 1');text(m.id,42,81,9,false,'0.8 0.9 0.85');text(out?'SA':'EN',520,42,25,true,'0.9 0.7 0.4');y=128;};
 const ensure=h=>{if(y+h>714)page()};
 const width=(s,size)=>bytes(s).reduce((a,c)=>a+Math.max(pdfFonts[0].widths[c]||600,pdfFonts[1].widths[c]||600),0)*size/1000;
 const wrap=(s,w,size)=>{const rows=[];for(const para of String(s||'Sin observaciones.').split('\n')){let line='';for(const word of para.split(/\s+/)){if(width(line+' '+word,size)>w&&line){rows.push(line);line=''}if(width(word,size)>w){for(const c of word){if(width(line+c,size)>w){rows.push(line);line=''}line+=c}}else line+=(line?' ':'')+word;}rows.push(line)}return rows;};
 const block=(s,x=42,w=528,size=10,bold=false)=>{for(const line of wrap(s,w,size)){ensure(size+6);text(line,x,y,size,bold);y+=size+6}};
 const field=(label,value)=>{const lines=wrap(value||'No registrado',394,10);ensure(18);text(label,42,y,9,true);for(const line of lines){ensure(16);text(line,168,y,10);y+=16}y+=4};
 page();const e=m.event||{};
 field('Evento',e.title);field('Cliente',e.client);field('Fecha del evento',`${e.date||''} · ${e.start||''} – ${e.end||''}`);field('Lugar / instalación',e.address);if(e.animators){field('Animadores',e.animators.join(', '));field('Chofer',e.driver)}else field('Responsables',e.staff);field('Registro',new Date(m.time).toLocaleString('es-HN',{timeZone:'America/Tegucigalpa'}));field('Registrado por',e.role);y+=8;
 for(const i of m.items){ensure(95);rect(42,y,528,29,'0.93 0.95 0.92');y+=6;block(`${i.name} · ${i.quantity} unidad(es)`,50,510,11,true);y+=10;if(!out)field('Estado(s) al salir',i.departureCondition||'No registrado');field(out?'Estado al salir':'Estado al entrar',i.condition);block('Observaciones',42,528,9,true);block(i.note||'Sin observaciones.');y+=14;}
 ensure(45);block('Observaciones generales',42,528,11,true);block(m.note||'Sin observaciones generales.');y+=12;ensure(115);rect(42,y,528,32,'0.93 0.95 0.92');text(`Total de unidades ${out?'entregadas':'recibidas'}: ${m.quantity}`,52,y+9,11,true);y+=67;text('________________________',42,y);text('________________________',330,y);y+=20;text('Entrega · Nombre y firma',42,y,9);text('Recibe · Nombre y firma',330,y,9);y+=24;text('Documento generado por el prototipo privado de El Club de Pon Pon.',42,y,8);pages.push(ops);
 pages.forEach((p,n)=>{ops=p;rect(42,747,528,1,'0.8 0.85 0.82');text('El Club de Pon Pon · Registro operativo',42,757,8);text(`${n+1} / ${pages.length}`,535,757,8)});
 const objects=['<< /Type /Catalog /Pages 2 0 R >>','','',''];
 for(let f=0;f<2;f++){const font=pdfFonts[f],descriptorId=objects.length+1,fileId=descriptorId+1;objects[2+f]=`<< /Type /Font /Subtype /TrueType /BaseFont /${font.name} /FirstChar 32 /LastChar 255 /Widths [${font.widths.slice(32).join(' ')}] /Encoding /WinAnsiEncoding /FontDescriptor ${descriptorId} 0 R >>`;objects.push(`<< /Type /FontDescriptor /FontName /${font.name} /Flags 32 /FontBBox [${font.bbox.join(' ')}] /ItalicAngle 0 /Ascent ${font.ascent} /Descent ${font.descent} /CapHeight 730 /StemV ${f?120:80} /FontFile2 ${fileId} 0 R >>`);objects.push(`<< /Length ${font.hex.length+1} /Length1 ${font.length} /Filter /ASCIIHexDecode >>\nstream\n${font.hex}>\nendstream`)}
 const ids=[];for(const p of pages){const id=objects.length+1,stream=p.join('\n');ids.push(id);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${id+1} 0 R >>`);objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`)}objects[1]=`<< /Type /Pages /Count ${ids.length} /Kids [${ids.map(i=>i+' 0 R').join(' ')}] >>`;
 let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((s,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${s}\nendobj\n`});const xref=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new TextEncoder().encode(pdf);
}
export function movementDownload(m){return {url:URL.createObjectURL(new Blob([movementPdf(m)],{type:'application/pdf'})),filename:`Hoja_${m.type==='SA'?'Salida':'Entrada'}_${m.id}.pdf`}}
export function downloadMovement(m){const file=movementDownload(m),a=document.createElement('a');a.href=file.url;a.download=file.filename;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(file.url),60000)}
